SELECT 
FROM seckill
WHERE status = 1
  AND start_time <= #{now}
  AND end_time > #{now}
ORDER BY start_time

SELECT 
FROM seckill
WHERE status = 1
  AND start_time >= #{startTime}
  AND start_time < #{endTime}
ORDER BY start_time

mapper.update:
UPDATE seckill
product_id = #{productId}, seckill_price = #{seckillPrice}, stock = #{stock}, limit_per_user = #{limitPerUser}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE seckill
SET stock = stock - #{quantity}
WHERE id = #{id}
  AND stock >= #{quantity}

mapper.select:
SELECT s.id, s.product_id as productId, s.seckill_price as seckillPrice, s.stock as stockCount, s.stock as stock, s.limit_per_user as limitPerUser, s.start_time as startTime, s.end_time as endTime, s.status, s.create_time as createTime, s.update_time as updateTime, p.name as productName, p.main_image as productMainImage, p.price as originalPrice FROM seckill s LEFT JOIN product p ON s.product_id = p.id
AND s.product_id = #{productId} AND s.status = #{status}
ORDER BY s.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM seckill s

     AND s.product_id = #{productId} 
     AND s.status = #{status}

SELECT COUNT(1)
FROM seckill
WHERE product_id = #{productId}
  AND status != 2
  AND (start_time < #{endTime} AND end_time > #{startTime})
  
      AND id != #{excludeId}
